import{_ as t,c as a,o as r,ae as o}from"./chunks/framework.Bi6zybwU.js";const h=JSON.parse('{"title":"How to Create Your First Drag and Drop Table with Ninja Tables","description":"How to Create Your First Drag and Drop Table with Ninja Tables","frontmatter":{"title":"How to Create Your First Drag and Drop Table with Ninja Tables","description":"How to Create Your First Drag and Drop Table with Ninja Tables"},"headers":[],"relativePath":"guide/drag-drop-tables/how-to-create-your-first-drag-and-drop-table-with-ninja-tables.md","filePath":"guide/drag-drop-tables/how-to-create-your-first-drag-and-drop-table-with-ninja-tables.md"}'),l={name:"guide/drag-drop-tables/how-to-create-your-first-drag-and-drop-table-with-ninja-tables.md"};function n(s,e,i,d,c,b){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="how-to-create-your-first-drag-and-drop-table-with-ninja-tables" tabindex="-1">How to Create Your First Drag and Drop Table with Ninja Tables <a class="header-anchor" href="#how-to-create-your-first-drag-and-drop-table-with-ninja-tables" aria-label="Permalink to &quot;How to Create Your First Drag and Drop Table with Ninja Tables&quot;">​</a></h1><p>Welcome to Ninja Tables! This tutorial will explain the most extraordinary feature, <strong>Drag and Drop Table</strong>. We will explore the possibilities of Ninja Tables and how to use them to create WordPress tables. So let’s get started and create our first Drag &amp; Drop table visually with Ninja Tables. When we go to the Ninja Tables dashboard, we will be asked to either <strong>Create Your First Table</strong> or <strong>Import Table</strong>. We will select the <strong>Create Your First Table</strong> button. <img src="https://ninjatables.com/wp-content/uploads/2025/05/Welcome-to-Ninja-Tables-UI-1024x536.png" alt="Welcome to Ninja Tables UI"> If you already have created tables earlier, then you will see a similar screen below and click on the <strong>+ Create New Table</strong> button. <img src="https://ninjatables.com/wp-content/uploads/2025/05/All-Tables-List-UI-1024x536.webp" alt="All Tables List UI"> Once you click the &quot;Add Table&quot; button, you will see a popup dialogue with multiple table creation options.</p><h2 id="create-drag-and-drop-table" tabindex="-1">Create Drag and Drop table <a class="header-anchor" href="#create-drag-and-drop-table" aria-label="Permalink to &quot;Create Drag and Drop table&quot;">​</a></h2><p>From the menu on the side, we&#39;ll pick <strong>Drag &amp; Drop Table</strong>. <img src="https://ninjatables.com/wp-content/uploads/2025/06/New-UI-drag-and-drop-table-1024x742.webp" alt="New UI drag and drop table"> You can name the table and select the number of rows and columns from here. Hit <strong>Create</strong> when you&#39;re done selecting. Or you can choose to <strong>import</strong> a table (using a URL or a CSV/JSON file). We&#39;ve created a table with 3 rows and 3 columns. After that, the live table interface looks like this: <img src="https://ninjatables.com/wp-content/uploads/2023/08/Add-row-columns-1024x559.png" alt="Add row columns"> The left section on the menu, grouped by <strong>General</strong> &amp; <strong>Advanced</strong>, contains table cell elements that you can drag and drop on the table. Four cell elements in the Advanced section are available in the Pro version only. The General elements include <strong><a href="https://ninjatables.com/docs/text-element/" target="_blank" rel="noreferrer">Text</a></strong>, <strong><a href="https://ninjatables.com/docs/button-element/" target="_blank" rel="noreferrer">Button</a></strong>, <strong><a href="https://ninjatables.com/docs/icon-element/" target="_blank" rel="noreferrer">Icon</a>, <a href="https://ninjatables.com/docs/star-rating-element-in-ninja-tables-drag-and-drop/" target="_blank" rel="noreferrer">Rating</a>, <a href="https://ninjatables.com/docs/list-element/" target="_blank" rel="noreferrer">List</a>, <a href="https://ninjatables.com/docs/html/" target="_blank" rel="noreferrer">HTML</a>, <a href="https://ninjatables.com/docs/shortcode-element/" target="_blank" rel="noreferrer">Shortcode</a>, <strong>and</strong> <a href="https://ninjatables.com/docs/image/" target="_blank" rel="noreferrer">Image</a></strong>. The Advanced or Pro version includes **<a href="https://ninjatables.com/docs/styled-list/" target="_blank" rel="noreferrer">Styled List</a>, <a href="https://ninjatables.com/docs/ribbon-element/" target="_blank" rel="noreferrer">Ribbon</a>, <a href="https://ninjatables.com/docs/progress/" target="_blank" rel="noreferrer">Progress</a>, <strong>and</strong> <a href="https://ninjatables.com/docs/text-icon-pro/" target="_blank" rel="noreferrer">Text Icon</a> **as below screenshot. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Advanced-table-elements-1024x425.png" alt="Advanced table elements"> The buttons at the top of the table are <strong>Manage Cells</strong> and <strong>Background</strong> features to operate on the cells, row/column add/delete/duplicate, and background colors. Above these buttons, you&#39;ll notice an auto-generated shortcode, a <strong>Preview</strong> button, and a blue <strong>Save Table</strong> button. When a table is done, hit the <strong>Save Table</strong> button and paste the shortcode anywhere on your website.</p><h2 id="customizable-premade-templates" tabindex="-1">Customizable premade templates <a class="header-anchor" href="#customizable-premade-templates" aria-label="Permalink to &quot;Customizable premade templates&quot;">​</a></h2><p>If you want to customize a table from a premade design, scroll down after the first window to &quot;Drag and Drop Table&quot; opens. There are 4 different table templates-</p><ul><li>Pricing tables</li><li>Comparison tables</li><li>Employee tables</li><li>Schedule tables</li></ul><h3 id="ninja-tables-free-templates" tabindex="-1">Ninja Tables free templates <a class="header-anchor" href="#ninja-tables-free-templates" aria-label="Permalink to &quot;Ninja Tables free templates&quot;">​</a></h3><p><img src="https://ninjatables.com/wp-content/uploads/2022/10/Screenshot_7-1024x468.png" alt="Table Templates"> Pick any table template and edit them to fit your purpose. Now we will be adding a Text element to the table by dragging on the Text Element and dropping it onto the table. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Drag-cell-element-1024x453.png" alt="Drag cell element and drop on table"> Now once an element is added to the table, clicking on it will reveal the customization options for the element. More on the customization per element is described separately in documentation later on. When you click on the dropped cell element, you can customize it however you need. <img src="https://ninjatables.com/wp-content/uploads/2023/08/Customize-table-cell-element-1024x583.png" alt="Customize table cell element"></p><ul><li>Add text</li><li>Font color</li><li>Font size</li><li>Text alignment</li><li>Font style</li><li>Cell spacing</li><li>Move cell</li><li>Duplicate</li><li>Delete Please check our documentation for more on settings, <a href="https://ninjatables.com/docs/responsive-table-design/" target="_blank" rel="noreferrer">responsiveness</a>, and <a href="https://ninjatables.com/docs-category/table-elements/" target="_blank" rel="noreferrer">elements</a>. Once all the customizations are done, click on the save button and check the preview. Now all there&#39;s left to do is paste this table on a page. Simply copy the auto-generated shortcode from above the table and paste it where you need it.</li></ul><h3 id="more-drag-and-drop-table-templates" tabindex="-1">More Drag and Drop Table Templates <a class="header-anchor" href="#more-drag-and-drop-table-templates" aria-label="Permalink to &quot;More Drag and Drop Table Templates&quot;">​</a></h3><p>We have created a dedicated page with <a href="https://ninjatables.com/free-table-templates/" target="_blank" rel="noreferrer">50+ table designs</a> just for you! These tables are ready to use as soon as you download the file. Many tables are created using the Drag and Drop builder function. Check out a few we handpicked for you and customize tables your way.</p><ul><li><a href="https://ninjatables.com/free-table-templates/staff-directory-template/" target="_blank" rel="noreferrer">Staff directory</a></li><li><a href="https://ninjatables.com/free-table-templates/product-rating-box/" target="_blank" rel="noreferrer">Product rating box</a></li><li><a href="https://ninjatables.com/free-table-templates/semester-schedule-table/" target="_blank" rel="noreferrer">Semester/class schedule</a></li><li><a href="https://ninjatables.com/free-table-templates/drag-and-drop-pricing-table/" target="_blank" rel="noreferrer">Simple pricing table</a></li><li><a href="https://ninjatables.com/free-table-templates/cricket-league-point-table/" target="_blank" rel="noreferrer">Cricket league points</a></li><li><a href="https://ninjatables.com/free-table-templates/comparison-product-table/" target="_blank" rel="noreferrer">Product comparison</a></li><li><a href="https://ninjatables.com/free-table-templates/nursing-care-plan/" target="_blank" rel="noreferrer">Nursing care plan</a> and more. So that’s it! Please check out our other documentation regarding the features of the Drag &amp; Drop Tables and enjoy creating tables visually with Ninja Tables!</li></ul>',13)])])}const m=t(l,[["render",n]]);export{h as __pageData,m as default};
